try:
    print('>>> f = getattr')
    print('>>> x = ""')
    print('>>> y = bytearray()')
    print('>>> f(x, y)')
    f = getattr
    x = ""
    y = bytearray()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
